            return ResponseEntity.ok(guardado);
        } catch (Exception e) {
            e.printStackTrace();
            try { TransactionAspectSupport.currentTransactionStatus().setRollbackOnly(); } catch (Exception ignore) {}
            return serverError(e, "/api/frontend/productos/" + productoId + "/pasos");
