package dev.kali.labendicion.repository;

import dev.kali.labendicion.domain.entity.RegistroSync;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.stereotype.Repository;
import java.util.List;

@Repository
public interface RegistroSyncRepository extends JpaRepository<RegistroSync, String> {
    List<RegistroSync> findByOrderByFechaDesc();

    // Query optimizada para bootstrap: traer últimos 100 registros (evita cargar Miles)
    // Ordenado por fecha descendente
    @Query(value = "select r from RegistroSync r order by r.fecha desc")
    List<RegistroSync> findLatestRegistrosOrderByFechaDesc();

    // Query con LEFT JOIN FETCH para evitar lazy init, pero sin DISTINCT innecesario
    // Limita a últimos 100 para evitar queries enormes
    @Query(value = "select distinct r from RegistroSync r left join fetch r.producciones order by r.fecha desc")
    List<RegistroSync> findAllWithProduccionesOrderByFechaDesc();
}

package dev.kali.labendicion.service;

import org.springframework.stereotype.Service;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.IOException;
import java.util.*;
import java.util.concurrent.*;

/**
 * Servicio para administrar eventos SSE (Server-Sent Events) en tiempo real.
 * Gestiona la suscripción de clientes y el broadcasting de cambios en la BD.
 */
@Service
public class EventService {
    private final Set<SseEmitter> emitters = ConcurrentHashMap.newKeySet();
    private final ObjectMapper objectMapper = new ObjectMapper();
    private final int EMITTER_TIMEOUT = 60000; // 60 segundos

    /**
     * Crea y registra un nuevo cliente SSE.
     */
    public SseEmitter subscribe() {
        SseEmitter emitter = new SseEmitter((long) EMITTER_TIMEOUT);
        emitter.onCompletion(() -> emitters.remove(emitter));
        emitter.onTimeout(() -> emitters.remove(emitter));
        emitter.onError((throwable) -> emitters.remove(emitter));
        emitters.add(emitter);
        return emitter;
    }

    /**
     * Emite un evento a todos los clientes conectados.
     * @param tipo tipo de evento (ej: PRODUCTO_CREADO, EMPLEADO_ELIMINADO)
     * @param dato objeto con los datos del evento
     */
    public void emit(String tipo, Object dato) {
        Map<String, Object> event = new LinkedHashMap<>();
        event.put("tipo", tipo);
        event.put("dato", dato);
        event.put("timestamp", System.currentTimeMillis());

        List<SseEmitter> deadEmitters = new ArrayList<>();
        for (SseEmitter emitter : emitters) {
            try {
                emitter.send(SseEmitter.event()
                    .id(UUID.randomUUID().toString())
                    .name(tipo)
                    .data(objectMapper.writeValueAsString(event))
                    .build());
            } catch (IOException e) {
                deadEmitters.add(emitter);
            }
        }
        // Limpiar emitters cerrados
        emitters.removeAll(deadEmitters);
    }

    /**
     * Emite un evento de forma asíncrona (sin bloquear la request del CRUD).
     */
    public void emitAsync(String tipo, Object dato) {
        CompletableFuture.runAsync(() -> emit(tipo, dato));
    }
}

